<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: facturas.php');exit;}
$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$motivo=trim($_POST['motivo']??'');if(!$id||$motivo===''){header('Location: facturas.php');exit;}
try{$mysqli->begin_transaction();$s=$mysqli->prepare("SELECT estado FROM ventas WHERE id=? FOR UPDATE");$s->bind_param('i',$id);$s->execute();$venta=$s->get_result()->fetch_assoc();if(!$venta||$venta['estado']!=='completada')throw new RuntimeException('La factura no existe o ya está anulada.');$s=$mysqli->prepare('SELECT producto_id,lote_id,cantidad FROM detalle_venta WHERE venta_id=?');$s->bind_param('i',$id);$s->execute();$items=$s->get_result();$prod=$mysqli->prepare('UPDATE productos SET stock=stock+? WHERE id=?');$lote=$mysqli->prepare('UPDATE lotes_producto SET cantidad_disponible=cantidad_disponible+? WHERE id=?');while($it=$items->fetch_assoc()){$q=(int)$it['cantidad'];$pid=(int)$it['producto_id'];$prod->bind_param('ii',$q,$pid);$prod->execute();if($it['lote_id']!==null){$lid=(int)$it['lote_id'];$lote->bind_param('ii',$q,$lid);$lote->execute();}}$u=$mysqli->prepare("UPDATE ventas SET estado='anulada', motivo_anulacion=? WHERE id=?");$u->bind_param('si',$motivo,$id);$u->execute();$mysqli->commit();header('Location: ver_factura.php?id='.$id);exit;}catch(Throwable $e){$mysqli->rollback();http_response_code(400);echo 'No se pudo anular la factura. '.htmlspecialchars($e->getMessage());}
